import {storyMaterial,inkEdges,meadowPatches} from './storybook-materials.js?v=2';
import * as T from 'three';
import {OrbitControls} from './vendor/OrbitControls.js';
const host=document.querySelector('#scene'),builder=location.pathname.includes('barn-builder');
let seed=41;const rand=()=>{seed=(Math.imul(seed,1664525)+1013904223)>>>0;return seed/4294967296;};
const scene=new T.Scene();scene.background=new T.Color('#e5e7da');scene.fog=new T.Fog('#e5e7da',220,350);
const camera=new T.PerspectiveCamera(32,1,.1,400),renderer=new T.WebGLRenderer({antialias:true,alpha:false,preserveDrawingBuffer:true});renderer.setPixelRatio(Math.min(devicePixelRatio,1.6));renderer.shadowMap.enabled=true;renderer.shadowMap.type=T.PCFSoftShadowMap;renderer.outputColorSpace=T.SRGBColorSpace;host.prepend(renderer.domElement);renderer.domElement.setAttribute('aria-label','Interactive 3D ranch scene');renderer.domElement.tabIndex=0;
const controls=new OrbitControls(camera,renderer.domElement);controls.enableDamping=true;controls.maxPolarAngle=Math.PI*.47;controls.minDistance=9;controls.maxDistance=240;controls.target.set(0,2,0);
scene.add(new T.HemisphereLight('#fff1d2','#7a8874',(builder?2.3:1.25)));const sun=new T.DirectionalLight('#fff0cd',builder?3:2.1);sun.position.set(-25,40,24);sun.castShadow=true;sun.shadow.mapSize.set(2048,2048);Object.assign(sun.shadow.camera,{left:-38,right:38,top:38,bottom:-38,far:100});sun.shadow.normalBias=.035;scene.add(sun);
function painted(base,kind='wood'){if(!builder)return storyMaterial(base,kind);let c=document.createElement('canvas');c.width=c.height=256;let x=c.getContext('2d');x.fillStyle=base;x.fillRect(0,0,256,256);for(let i=0;i<550;i++){let a=rand()*256,b=rand()*256;x.strokeStyle=i%2?'#fff8dc18':'#253a2c18';x.lineWidth=.4+rand()*3;x.beginPath();x.moveTo(a,b);x.lineTo(a+(kind==='ground'?rand()*34:rand()*3),b+8+rand()*45);x.stroke();}const tex=new T.CanvasTexture(c);tex.colorSpace=T.SRGBColorSpace;tex.wrapS=tex.wrapT=T.RepeatWrapping;return new T.MeshStandardMaterial({map:tex,roughness:1,color:0xffffff});}
const wood=painted('#95866a'),trim=painted('#e6d6af'),red=painted(builder?'#c38365':'#d5764f'),roof=painted(builder?'#557f80':'#338e91'),ground=painted('#a9b778','ground'),soil=painted('#9c8e66','ground');const dark=new T.MeshStandardMaterial({color:'#354a3e',roughness:1}),leaves=['#39804f','#529c58','#77b667'].map(x=>painted(x,builder?'ground':'foliage'));
function mesh(g,m,x=0,y=0,z=0,parent=scene){const a=new T.Mesh(g,m);a.position.set(x,y,z);a.castShadow=true;a.receiveShadow=true;parent.add(a);if(!builder)inkEdges(a);return a;}
function box(w,h,d,x,y,z,m=wood,parent=scene){return mesh(new T.BoxGeometry(w,h,d),m,x,y,z,parent);}
function beam(a,b,r=.12,m=wood,parent=scene,r2=r){const A=new T.Vector3(...a),B=new T.Vector3(...b),o=mesh(new T.CylinderGeometry(r2,r,A.distanceTo(B),7),m,0,0,0,parent);o.position.copy(A).add(B).multiplyScalar(.5);o.quaternion.setFromUnitVectors(new T.Vector3(0,1,0),B.sub(A).normalize());return o;}
function barn({bays=4,pitch=1.9,wear=.5}={},parent=scene){const g=new T.Group();parent.add(g);const w=6,d=bays*2,h=3.8;box(w+.35,.4,d+.35,0,.2,0,soil,g);box(w,h,d,0,h/2+.35,0,red,g);
// The frame determines bay spacing, wall boards and openings.
for(let i=0;i<=bays;i++){let z=-d/2+i*2;for(let x of [-3,3])box(.19,h+.1,.2,x,h/2+.4,z,trim,g);beam([-3,h+.4,z],[0,h+pitch+.4,z],.09,wood,g);beam([0,h+pitch+.4,z],[3,h+.4,z],.09,wood,g);}
for(let side of [-1,1]){let panel=box(Math.hypot(3.4,pitch),.22,d+.7,side*1.7,h+.4+pitch/2,0,roof,g);panel.rotation.z=-side*Math.atan2(pitch,3.4);for(let z=-d/2+.5;z<d/2;z+=.5){if(rand()<wear)box(.015,.5+rand()*2,.035,side*3.01,1+rand()*2,z,wood,g);}}
// Front gable, trimmed opening, sliding door and diagonal braces.
const shape=new T.Shape();shape.moveTo(-3,0);shape.lineTo(3,0);shape.lineTo(0,pitch);shape.closePath();for(let z of [-d/2,d/2]){let a=mesh(new T.ShapeGeometry(shape),red,0,h+.35,z,g);if(z<0)a.rotation.y=Math.PI;}
box(2.7,2.85,.12,0,1.8,d/2+.08,dark,g);for(let x of [-1.5,1.5])box(.17,3.1,.23,x,1.9,d/2+.16,trim,g);box(3.25,.2,.25,0,3.45,d/2+.17,trim,g);
for(let x of [-.69,.69]){box(1.28,2.7,.12,x,1.8,d/2+.17,wood,g);beam([x-.56,.5,d/2+.25],[x+.56,3.05,d/2+.25],.055,trim,g);beam([x+.56,.5,d/2+.25],[x-.56,3.05,d/2+.25],.055,trim,g);}
for(let side of [-1,1])for(let i=0;i<bays;i++){const z=-d/2+1+i*2;box(.1,.85,.85,side*3.07,2.5,z,dark,g);box(.15,.07,.9,side*3.1,2.5,z,trim,g);box(.15,.9,.07,side*3.1,2.5,z,trim,g);}
box(.8,.8,.8,0,h+pitch+.65,0,trim,g);let cap=mesh(new T.ConeGeometry(.8,.65,4),roof,0,h+pitch+1.35,0,g);cap.rotation.y=Math.PI/4;return g;}
function crown(x,y,z,s,parent=scene){for(let i=0;i<5;i++){let a=mesh(new T.IcosahedronGeometry(1,1),leaves[i%3],x+(rand()-.5)*s,y+rand()*.35,z+(rand()-.5)*s,parent);a.scale.set(s*.72,s*.48,s*.55);a.rotation.y=rand()*6;}}
function tree(x,z,s=1,hero=false){const g=new T.Group();g.position.set(x,0,z);g.scale.setScalar(s);scene.add(g);const points=hero?[[0,0,0],[.5,2,0],[-.3,4,.1],[.2,6,0],[.5,8,.2]]:[[0,0,0],[0,2,0],[.2,4,0]];for(let i=1;i<points.length;i++)beam(points[i-1],points[i],hero?.65-i*.1:.23,wood,g,hero?.55-i*.1:.12);if(hero){for(let i=0;i<7;i++){let y=3+i*.65,a=i*2.4,len=3.6-i*.28,end=[Math.cos(a)*len,y+.8,Math.sin(a)*len];beam([0,y,0],end,.22,wood,g,.06);crown(...end,2.3-i*.1,g);}for(let i=0;i<5;i++)beam([0,.5,0],[Math.cos(i*1.3)*1.7,.08,Math.sin(i*1.3)*1.7],.25,wood,g,.06);crown(.5,8,.2,1.8,g);}else crown(0,4,0,2.2,g);}
function ribbon(points,width,mat,y=.08){let curve=new T.CatmullRomCurve3(points.map(([x,z])=>new T.Vector3(x,y,z))),p=[],uv=[],idx=[];for(let i=0;i<=80;i++){let t=i/80,v=curve.getPoint(t),d=curve.getTangent(t),n=new T.Vector3(-d.z,0,d.x);for(let s of [-1,1]){p.push(v.x+n.x*width*s/2,y,v.z+n.z*width*s/2);uv.push(t*4,(s+1)/2);}if(i<80){let k=i*2;idx.push(k,k+2,k+1,k+1,k+2,k+3);}}let g=new T.BufferGeometry();g.setAttribute('position',new T.Float32BufferAttribute(p,3));g.setAttribute('uv',new T.Float32BufferAttribute(uv,2));g.setIndex(idx);g.computeVertexNormals();mat.side=T.DoubleSide;const strip=mesh(g,mat);strip.castShadow=false;}
const query=new URLSearchParams(location.search);const recipe={bays:Math.max(3,Math.min(6,+query.get('bays')||4)),pitch:Math.max(1.2,Math.min(2.6,+query.get('pitch')||1.9)),wear:Math.max(.1,Math.min(.9,+query.get('wear')||.5))};const buildingSeed=+query.get('seed')||41;
let currentBarn;
function setup(){if(builder){box(26,.5,24,0,-.35,0,ground);seed=buildingSeed;currentBarn=barn(recipe);}else{let island=mesh(new T.CylinderGeometry(25,24,1.4,64),ground,0,-.7,0);island.scale.z=.82;meadowPatches(scene);const water=new T.MeshStandardMaterial({color:'#8fc4ba',roughness:1});ribbon([[-23,-6],[-14,-8],[-5,-6],[3,-8],[13,-6],[22,-3]],2.4,water,.07);ribbon([[-4,20],[-5,12],[-4,4],[-6,0],[-8,-6]],2.1,painted('#c4b18b','ground'),.08);seed=buildingSeed;let b=barn(recipe);b.position.set(-6,0,2);b.rotation.y=-.12;tree(9,5,1.2,true);for(let i=0;i<32;i++){let a=i/32*Math.PI*2,x=Math.cos(a)*(18+rand()*5),z=Math.sin(a)*(14+rand()*4);if(z>10&&Math.abs(x)<10)continue;tree(x,z,.55+rand()*.45);}for(let i=0;i<9;i++){let x=1+i*1.6;beam([x,0,12],[x,1.3+rand()*.1,12],.09);if(i)for(let h of [.5,1.1])beam([x-1.6,h,12],[x,h,12],.055);}for(let z=-9;z<-4;z+=.4)box(3.3,.16,.3,-8,.3,z,wood);for(let i=0;i<3;i++){box(2,.22,3,1+i*2.6,.15,-1,wood);box(1.7,.1,2.7,1+i*2.6,.3,-1,soil);for(let j=0;j<6;j++){let a=mesh(new T.IcosahedronGeometry(.28,0),leaves[j%3],.6+i*2.6+(j%2)*.7,.55,-2+Math.floor(j/2)*.8);a.scale.y=.6;}}for(let i=0;i<25;i++){let x=-20+rand()*40,z=-8+Math.sin(x*.2);let a=mesh(new T.DodecahedronGeometry(.25+rand()*.35,0),soil,x,.17,z+1.8);a.scale.y=.5;}}}
setup();if(!builder){document.querySelector('.scene-note small').textContent='ABBIE\u2019S WORLD';document.querySelector('.scene-note p').textContent='A little world in ink and sunshine. Drag to orbit, pinch to zoom.';}
function view(target,pos){controls.target.set(...target);camera.position.set(...pos);controls.update();}
function home(){const factor=host.clientWidth<600?(builder?1.6:2.7):1;view([0,2,0],(builder?[16,13,23]:[38,34,49]).map(v=>v*factor));}home();
document.querySelector('#home-view').onclick=home;document.querySelector('#tree-view').onclick=()=>view([9,4,5],[25,14,25]);document.querySelector('#barn-view').onclick=()=>view(builder?[0,2,0]:[-6,2,2],builder?[13,9,17]:[10,11,23]);document.querySelector('#turn-view').onclick=()=>{const d=camera.position.clone().sub(controls.target);d.applyAxisAngle(new T.Vector3(0,1,0),Math.PI/6);camera.position.copy(controls.target).add(d);controls.update();};document.querySelector('#zoom-view').onclick=()=>{camera.position.lerp(controls.target,.18);controls.update();};
if(builder){document.querySelector('#tree-view').hidden=true;const form=document.querySelector('#barn-form');form.onsubmit=e=>{e.preventDefault();seed=+form.elements.seed.value;scene.remove(currentBarn);currentBarn.traverse(o=>{if(o.geometry)o.geometry.dispose();});currentBarn=barn({bays:+form.elements.bays.value,pitch:+form.elements.pitch.value,wear:+form.elements.wear.value});document.querySelector('#use-barn').href='/3d?'+new URLSearchParams(new FormData(form));document.querySelector('#scene-status').textContent=`${form.elements.bays.value} bays · seed ${seedInputValue()} · rebuilt`;};const seedInputValue=()=>form.elements.seed.value;document.querySelector('#new-barn').onclick=()=>{form.elements.seed.value=+form.elements.seed.value+1;form.requestSubmit();};}
const resize=()=>{const w=host.clientWidth,h=host.clientHeight;renderer.setSize(w,h);camera.aspect=w/h;camera.updateProjectionMatrix();};new ResizeObserver(resize).observe(host);resize();document.querySelector('#scene-status').textContent=builder?'Adjust the frame, then build':'Drag to explore';renderer.setAnimationLoop(()=>{controls.update();renderer.render(scene,camera);});renderer.domElement.addEventListener('webglcontextlost',e=>{e.preventDefault();document.querySelector('#scene-status').textContent='Graphics paused. Reload to restore the scene.';});

window.RanchView?.register('ranch3d',()=>({builder,camera:{position:camera.position.toArray(),target:controls.target.toArray(),fov:camera.fov},recipe:builder?Object.fromEntries(new FormData(document.querySelector('#barn-form'))):Object.fromEntries(new URLSearchParams(location.search))}),()=>renderer.render(scene,camera));
